param([Parameter(Mandatory=$true)][string]$Journal,[Parameter(Mandatory=$true)][string]$Output)
$ErrorActionPreference='Stop';$lines=@(Get-Content -LiteralPath $Journal);if((Get-Item $Journal).Length-gt65536){throw 'Journal exceeds frozen bound'}
$requests=@($lines|Where-Object {$_-match'event=REQUEST_API_INVOKING\b'}).Count;$returned=@($lines|Where-Object {$_-match'event=REQUEST_API_RETURNED\b'}).Count;$callbacks=@($lines|Where-Object {$_-match'event=RESULT_RECEIVED\b'});$rejected=@($lines|Where-Object {$_-match'event=CALLBACK_REJECTED\b'}).Count
if($requests-gt1-or$returned-gt1-or$callbacks.Count-gt1){throw 'Harness one-shot evidence invariant violated; preserve evidence and investigate'}
$pass=@($callbacks|Where-Object {$_-match'state=GRANTED\b'-and$_-match'vid=6353 pid=11521 '-and$_-match'hasPermission=true'-and$_-match'callbackGranted=true'-and$_-match'verifiedPermission=true'}).Count-eq1-and$requests-eq1-and$returned-eq1
$synthetic=$lines.Count-gt0-and$lines[0]-match'^SYNTHETIC';$r=[ordered]@{scope=if($synthetic){'HOST TOOL TEST ONLY'}else{'Frozen app journal; corroborate artifact and capture provenance'};verdict=if($pass-and$synthetic){'SYNTHETIC PASS; NOT LIVE M5 PASS'}elseif($pass){'M5 PASS'}else{'M5 INCONCLUSIVE; manual restriction/denial review required'};requestsInvoking=$requests;requestsReturned=$returned;acceptedCallbacks=$callbacks.Count;rejectedCallbacks=$rejected;grantedAndVerified=$pass;callbackNonceAndDeviceMatch='Accepted RESULT_RECEIVED implies frozen audited nonce/device gates passed; raw nonce is not persisted, so not independently compared';identities=@($lines|Where-Object {$_-match'event=(DEVICE_APPEARED_OR_CHANGED|TARGET_SEEN|RESULT_RECEIVED)\b'});journalSHA256=(Get-FileHash $Journal).Hash;noAutomaticNextMilestone=$true}
$r|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $Output;$r|ConvertTo-Json -Depth 5
